#!/usr/bin/env node
"use strict";

// Compact all-in-one JS smoke runner.  It intentionally keeps the former
// focused cases as in-memory modules so the test tree stays small while the
// individual assertions remain easy to debug.
const Module = require("module");
const path = require("path");
const moduleSources = {
  "./extension_root": "\"use strict\";\n\nconst fs = require(\"fs\");\nconst path = require(\"path\");\n\nfunction exists(...parts) {\n  return fs.existsSync(path.join(...parts));\n}\n\nfunction walkUp(starts) {\n  const seen = new Set();\n  const out = [];\n  for (const start of starts.filter(Boolean)) {\n    let current = path.resolve(start);\n    while (!seen.has(current)) {\n      seen.add(current);\n      out.push(current);\n      const parent = path.dirname(current);\n      if (parent === current) break;\n      current = parent;\n    }\n  }\n  return out;\n}\n\nfunction isExtensionRoot(dir) {\n  return Boolean(\n    dir &&\n      exists(dir, \"package.json\") &&\n      exists(dir, \"src\", \"extension.js\") &&\n      exists(dir, \"nytrix.tmLanguage.json\")\n  );\n}\n\nfunction isNytrixRoot(dir) {\n  return Boolean(dir && exists(dir, \"lib\") && (exists(dir, \"make\") || exists(dir, \"build\", \"release\")));\n}\n\nfunction findExtensionRoot() {\n  if (process.env.NYTRIX_VSCODE_EXTENSION_ROOT) {\n    return path.resolve(process.env.NYTRIX_VSCODE_EXTENSION_ROOT);\n  }\n  for (const candidate of walkUp([__dirname, process.cwd()])) {\n    if (isExtensionRoot(candidate)) return candidate;\n  }\n  throw new Error(\"cannot find VS Code Nytrix extension root\");\n}\n\nfunction findNytrixRoot() {\n  if (process.env.NYTRIX_REPO_ROOT) {\n    return path.resolve(process.env.NYTRIX_REPO_ROOT);\n  }\n  const candidates = walkUp([\n    process.cwd(),\n    __dirname,\n    path.resolve(__dirname, \"..\"),\n    path.join(process.env.HOME || \"\", \"nytrix\")\n  ]).filter(isNytrixRoot);\n\n  for (const binary of [\"ny-lsp\", \"ny\"]) {\n    const withBinary = candidates.find((candidate) => exists(candidate, \"build\", \"release\", binary));\n    if (withBinary) return withBinary;\n  }\n  return candidates[0] || path.resolve(findExtensionRoot(), \"..\");\n}\n\nmodule.exports = {\n  findExtensionRoot,\n  findNytrixRoot,\n  isExtensionRoot,\n  isNytrixRoot\n};\n",
  "./harness": "\"use strict\";\n\nfunction formatError(err) {\n  return err && err.stack ? err.stack : String(err);\n}\n\nasync function runAll(cases) {\n  const started = Date.now();\n  let passed = 0;\n  try {\n    for (const [name, main] of cases) {\n      const caseStarted = Date.now();\n      await main();\n      passed += 1;\n      console.log(`${name}: ok (${Date.now() - caseStarted}ms)`);\n    }\n    console.log(`js smoke: ${passed}/${cases.length} passed in ${Date.now() - started}ms`);\n  } catch (err) {\n    console.error(formatError(err));\n    console.error(`js smoke: ${passed}/${cases.length} passed before failure`);\n    process.exit(1);\n  }\n}\n\nclass Position {\n  constructor(line, character) {\n    this.line = line;\n    this.character = character;\n  }\n}\n\nclass Range {\n  constructor(startLine, startCharacter, endLine, endCharacter) {\n    this.start = new Position(startLine, startCharacter);\n    this.end = new Position(endLine, endCharacter);\n  }\n}\n\nfunction fileUri(filePath) {\n  return {\n    scheme: \"file\",\n    fsPath: filePath,\n    toString() {\n      return filePath;\n    }\n  };\n}\n\nfunction document(filePath, text) {\n  const lines = text.split(/\\r?\\n/);\n  return {\n    languageId: \"nytrix\",\n    uri: fileUri(filePath),\n    lineCount: lines.length,\n    getText(range) {\n      if (!range) return text;\n      return range.start.line === range.end.line\n        ? lines[range.start.line].slice(range.start.character, range.end.character)\n        : \"\";\n    },\n    lineAt(index) {\n      return { text: lines[index] };\n    },\n    getWordRangeAtPosition(position, regex = /[A-Za-z_][A-Za-z0-9_.]*/g) {\n      const line = lines[position.line] || \"\";\n      const flags = regex.flags.includes(\"g\") ? regex.flags : `${regex.flags}g`;\n      const word = new RegExp(regex.source, flags);\n      let match;\n      while ((match = word.exec(line))) {\n        const start = match.index;\n        const end = start + match[0].length;\n        if (position.character >= start && position.character <= end) {\n          return new Range(position.line, start, position.line, end);\n        }\n      }\n      return null;\n    }\n  };\n}\n\nmodule.exports = { runAll, Position, Range, fileUri, document };\n",
  "./vscode_stub": "\"use strict\";\n\nconst Module = require(\"module\");\nconst path = require(\"path\");\nconst { findExtensionRoot } = require(\"./extension_root\");\n\nfunction loadExtensionWithVscode(fakeVscode) {\n  const extensionPath = path.join(findExtensionRoot(), \"src\", \"extension.js\");\n  const previous = Module._load;\n  Module._load = function patchedLoad(request, parent, isMain) {\n    if (request === \"vscode\") {\n      return fakeVscode;\n    }\n    return previous.call(this, request, parent, isMain);\n  };\n  try {\n    delete require.cache[require.resolve(extensionPath)];\n    return require(extensionPath);\n  } finally {\n    Module._load = previous;\n  }\n}\n\nmodule.exports = {\n  loadExtensionWithVscode\n};\n",
  "./metadata_smoke": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst fs = require(\"fs\");\nconst path = require(\"path\");\nconst { findExtensionRoot } = require(\"./extension_root\");\nconst { productionDependencyDirs } = require(\"../scripts/package\");\n\nconst root = findExtensionRoot();\nconst read = (...parts) => fs.readFileSync(path.join(root, ...parts), \"utf8\");\nconst json = (...parts) => JSON.parse(read(...parts));\n\nconst manifest = json(\"package.json\");\nconst grammar = json(\"nytrix.tmLanguage.json\");\nconst snippets = json(\"snippets\", \"nytrix.code-snippets\");\nconst extensionSource = read(\"src\", \"extension.js\");\n\nfunction regexSet(text, pattern, map = (match) => match[1]) {\n  return new Set([...String(text).matchAll(pattern)].map(map));\n}\n\nfunction commandActivations() {\n  return new Set((manifest.activationEvents || [])\n    .filter((event) => event.startsWith(\"onCommand:nytrix.\"))\n    .map((event) => event.slice(\"onCommand:\".length)));\n}\n\nfunction contributedCommands() {\n  return new Set((manifest.contributes.commands || []).map((command) => command.command));\n}\n\nfunction registeredCommands() {\n  return regexSet(extensionSource, /\\[\\s*\"(nytrix\\.[A-Za-z0-9_.-]+)\"\\s*,/g);\n}\n\nfunction walkthroughCommands() {\n  const events = (manifest.contributes.walkthroughs || [])\n    .flatMap((walkthrough) => walkthrough.steps || [])\n    .flatMap((step) => step.completionEvents || []);\n  return new Set(events\n    .filter((event) => event.startsWith(\"onCommand:nytrix.\"))\n    .map((event) => event.slice(\"onCommand:\".length)));\n}\n\nfunction configKeysFromCode() {\n  return regexSet(extensionSource, /cfg\\(\\)\\.get\\(\"([^\"]+)\"/g, (match) => `nytrix.${match[1]}`);\n}\n\nfunction flattenStrings(value) {\n  if (typeof value === \"string\") return [value];\n  if (Array.isArray(value)) return value.flatMap(flattenStrings);\n  return value && typeof value === \"object\" ? Object.values(value).flatMap(flattenStrings) : [];\n}\n\nfunction assertSubset(name, subset, superset) {\n  const missing = [...subset].filter((item) => !superset.has(item)).sort();\n  assert.strictEqual(missing.length, 0, `${name} missing: ${missing.join(\", \")}`);\n}\n\nfunction assertNoOverlap(name, left, right) {\n  const overlap = [...left].filter((item) => right.has(item)).sort();\n  assert.strictEqual(overlap.length, 0, `${name}: ${overlap.join(\", \")}`);\n}\n\nfunction assertLineListContains(name, file, required) {\n  const lines = new Set(read(file).split(/\\r?\\n/).map((line) => line.trim()).filter(Boolean));\n  const missing = required.filter((line) => !lines.has(line));\n  assert.strictEqual(missing.length, 0, `${name} missing: ${missing.join(\", \")}`);\n}\n\nfunction relativePackageDirs() {\n  return new Set(productionDependencyDirs(root).map((dir) => path.relative(root, dir).replace(/\\\\/g, \"/\")));\n}\n\nfunction main() {\n  assert.strictEqual(manifest.version, \"0.1.7\", \"package version should be bumped\");\n  assert.strictEqual(manifest.scripts.prepackage, \"npm run validate\", \"package should validate before building the VSIX\");\n  assert.strictEqual(manifest.scripts.package, \"node scripts/package.js\", \"package should use deterministic package-lock dependency discovery\");\n  assert.strictEqual(manifest.scripts[\"package:ls\"], \"node scripts/package.js --list\", \"package listing should use the same deterministic dependency discovery\");\n  assert.strictEqual(manifest.galleryBanner.color, \"#0D1117\", \"marketplace banner should match the Nytrix dark background\");\n  assert.strictEqual(manifest.qna, \"https://github.com/nytrix-lang/nytrix/issues\", \"Q&A should point at the issue tracker\");\n  assert.deepStrictEqual(manifest.extensionKind, [\"workspace\"], \"extension should run on the workspace side for tool processes\");\n  assert(manifest.capabilities && manifest.capabilities.untrustedWorkspaces, \"workspace trust capabilities should be declared\");\n\n  const activated = commandActivations();\n  const contributed = contributedCommands();\n  const registered = registeredCommands();\n  const hidden = new Set([...registered].filter((command) => !contributed.has(command)));\n\n  assertSubset(\"contributed commands not registered\", contributed, registered);\n  assertSubset(\"hidden registered commands not activated\", hidden, activated);\n  assertSubset(\"walkthrough commands not contributed\", walkthroughCommands(), contributed);\n  assertNoOverlap(\"contributed commands should rely on implicit activation\", activated, contributed);\n  assert((manifest.contributes.walkthroughs || []).length > 0, \"extension should include an onboarding walkthrough\");\n\n  const configProperties = new Set(Object.keys(manifest.contributes.configuration.properties || {}));\n  assertSubset(\"configuration keys used by code but not contributed\", configKeysFromCode(), configProperties);\n\n  for (const file of [\n    \"src/extension.js\", \"nytrix.tmLanguage.json\",\n    \"snippets/nytrix.code-snippets\", \"README.md\", \"LICENSE\",\n    \"logo.png\", \"scripts/package.js\"\n  ]) {\n    assert(fs.existsSync(path.join(root, file)), `missing packaged asset ${file}`);\n  }\n\n  const packageDirs = relativePackageDirs();\n  assertSubset(\"production dependency paths\", new Set([\n    \"\", \"node_modules/vscode-languageclient\", \"node_modules/vscode-jsonrpc\",\n    \"node_modules/vscode-languageserver-protocol\", \"node_modules/vscode-languageserver-types\", \"node_modules/semver\"\n  ]), packageDirs);\n  for (const forbidden of [\"node_modules/@vscode/vsce\", \"node_modules/vscode\", \"test\", \"build\", \"cache\", \"dist\", \"out\"]) {\n    assert(!packageDirs.has(forbidden), `package dependency set should not include ${forbidden}`);\n  }\n\n  const snippetText = flattenStrings(snippets).join(\"\\n\");\n  assert(!/fn\\s+[A-Za-z_][A-Za-z0-9_]*\\([^)]*\\)\\s*:/.test(snippetText), \"snippets should use current function return syntax\");\n  assert(!/\\$\\{[0-9]+:Type\\}:\\s*\\$\\{[0-9]+:field\\}/.test(snippetText), \"field snippets should use type-name order\");\n\n  const declarations = grammar.repository && grammar.repository.declaration && grammar.repository.declaration.patterns || [];\n  assert(declarations.some((pattern) => pattern.name === \"meta.function.definition.nytrix\" && pattern.begin), \"grammar should scope function headers\");\n  assert(declarations.some((pattern) => pattern.name === \"meta.extern.block.nytrix\"), \"grammar should scope extern blocks\");\n  assert(flattenStrings(grammar).some((text) => text.includes(\"meta.parameter.typed.nytrix\")), \"grammar should scope typed parameters\");\n\n  assertLineListContains(\"gitignore generated output rules\", \".gitignore\", [\n    \"*.vsix\", \"node_modules/\", \"build/\", \"cache/\", \"dist/\", \"out/\", \".vscode-test/\", \"test/.artifacts/\"\n  ]);\n  assertLineListContains(\"vscodeignore generated output rules\", \".vscodeignore\", [\n    \"node_modules/**\", \".gitignore\", \"!node_modules/vscode-languageclient/**\",\n    \"scripts/**\", \"test/**\", \"build/**\", \"cache/**\", \"dist/**\", \"out/**\", \"*.vsix\"\n  ]);\n\n}\n\nmodule.exports = main;\n",
  "./bootstrap_smoke": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst os = require(\"os\");\nconst path = require(\"path\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nconst fakeVscode = {\n  workspace: {\n    workspaceFolders: [],\n    getConfiguration() {\n      const values = {\n        \"bootstrap.mode\": \"prompt\",\n        \"bootstrap.root\": \"${home}/.cache/nytrix-bootstrap\",\n        \"bootstrap.repo\": \"https://github.com/nytrix-lang/nytrix\",\n        \"bootstrap.ref\": \"main\"\n      };\n      return {\n        get(key, fallback) {\n          return Object.prototype.hasOwnProperty.call(values, key) ? values[key] : fallback;\n        }\n      };\n    }\n  },\n  window: {},\n  languages: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nfunction main() {\n  const root = extension.__test.bootstrapRoot();\n  assert.strictEqual(root, path.join(os.homedir(), \".cache\", \"nytrix-bootstrap\"));\n  assert.strictEqual(extension.__test.bootstrapRepo(), \"https://github.com/nytrix-lang/nytrix\");\n  assert.strictEqual(extension.__test.bootstrapRef(), \"main\");\n\n  const toolPaths = extension.__test.bootstrapToolPaths(\"/tmp/nytrix-bootstrap\");\n  assert.strictEqual(toolPaths.root, \"/tmp/nytrix-bootstrap\");\n  assert(toolPaths.ny.endsWith(\"/build/release/ny\"), \"expected ny path under build/release\");\n  assert(toolPaths.lsp.endsWith(\"/build/release/ny-lsp\"), \"expected ny-lsp path under build/release\");\n  assert(toolPaths.makeScript.endsWith(\"/make\"), \"expected repo make script path\");\n\n  const plan = extension.__test.bootstrapPlan(\"/tmp/nytrix-bootstrap\");\n  assert.strictEqual(plan.repo, \"https://github.com/nytrix-lang/nytrix\");\n  assert.strictEqual(plan.ref, \"main\");\n  assert.deepStrictEqual(\n    plan.cloneArgs,\n    [\"clone\", \"--depth\", \"1\", \"--branch\", \"main\", \"https://github.com/nytrix-lang/nytrix\", \"/tmp/nytrix-bootstrap\"]\n  );\n  assert.strictEqual(plan.buildCommand, plan.paths.makeScript, \"expected non-Windows bootstrap to use repo make script\");\n\n}\n\nmodule.exports = main;\n",
  "./code_actions_smoke": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst path = require(\"path\");\nconst { findNytrixRoot } = require(\"./extension_root\");\nconst { Position, Range, fileUri } = require(\"./harness\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nconst repoRoot = findNytrixRoot();\nprocess.env.NYTRIX_FMT = process.env.NYTRIX_FMT || path.join(repoRoot, \"build\", \"release\", \"ny-fmt\");\n\nclass Kind {\n  constructor(value) {\n    this.value = value;\n  }\n\n  append(segment) {\n    return new Kind(`${this.value}.${segment}`);\n  }\n}\n\nclass WorkspaceEdit {\n  constructor() {\n    this.edits = [];\n  }\n\n  insert(uri, position, text) {\n    this.edits.push({ uri, position, text });\n  }\n}\n\nclass CodeAction {\n  constructor(title, kind) {\n    this.title = title;\n    this.kind = kind;\n    this.diagnostics = undefined;\n    this.command = undefined;\n    this.edit = undefined;\n    this.isPreferred = false;\n  }\n}\n\nclass CodeLens {\n  constructor(range, command) {\n    this.range = range;\n    this.command = command;\n  }\n}\n\nconst fakeVscode = {\n  CodeAction,\n  CodeLens,\n  CodeActionKind: {\n    QuickFix: new Kind(\"quickfix\"),\n    Source: new Kind(\"source\"),\n    SourceFixAll: new Kind(\"source.fixAll\"),\n    SourceOrganizeImports: new Kind(\"source.organizeImports\")\n  },\n  WorkspaceEdit,\n  Position,\n  Range,\n  Uri: {\n    file: fileUri\n  },\n  DiagnosticSeverity: {\n    Error: 0,\n    Warning: 1,\n    Information: 2,\n    Hint: 3\n  },\n  languages: {\n    getDiagnostics() {\n      return [];\n    }\n  },\n  workspace: {\n    workspaceFolders: [],\n    textDocuments: [],\n    getConfiguration() {\n      return {\n        get(_key, fallback) {\n          return fallback;\n        }\n      };\n    },\n    getWorkspaceFolder() {\n      return null;\n    }\n  },\n  window: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nasync function main() {\n  const provider = new extension.__test.NytrixCodeActionProvider();\n\n  const lines = [\n    \"use std.os *\",\n    \"use std.core(print)\",\n    \"\",\n    \"fn helper(int value) int {\",\n    \"   return value + 1\",\n    \"}\",\n    \"\",\n    \"print(helper(41))\"\n  ];\n\n  const uri = fakeVscode.Uri.file(\"/tmp/assist_test.ny\");\n  const document = {\n    languageId: \"nytrix\",\n    uri,\n    lineCount: lines.length,\n    lineAt(index) {\n      return { text: lines[index] };\n    }\n  };\n\n  const diagnostics = [\n    {\n      code: \"NYFMT1300\",\n      range: new fakeVscode.Range(0, 11, 0, 12)\n    },\n    {\n      code: \"NYFMT2000\",\n      range: new fakeVscode.Range(3, 0, 3, 1)\n    },\n    {\n      code: \"NYAUD1001\",\n      range: new fakeVscode.Range(3, 0, 3, 1)\n    }\n  ];\n\n  const actions = provider.provideCodeActions(document, new fakeVscode.Range(0, 0, 0, 1), { diagnostics });\n  const titles = actions.map((action) => action.title);\n\n  for (const title of [\n    \"Normalize imports with ny-fmt\",\n    \"Insert doc string stub\",\n    \"Apply Nytrix optimizations\",\n    \"Fix all Nytrix style with ny-fmt\",\n    \"Organize Nytrix imports\",\n    \"Analyze current Nytrix file\",\n    \"Check current Nytrix file\"\n  ]) {\n    assert(titles.includes(title), `missing code action ${title}`);\n  }\n\n  const docAction = actions.find((action) => action.title === \"Insert doc string stub\");\n  assert(docAction && docAction.edit, \"missing doc stub workspace edit\");\n  assert(docAction.edit.edits.length === 1, \"expected one doc edit\");\n  assert(\n    docAction.edit.edits[0].text.includes('\"Describe helper.\"'),\n    \"doc stub should describe helper\"\n  );\n\n  const importAction = actions.find((action) => action.title === \"Normalize imports with ny-fmt\");\n  assert(importAction.command && importAction.command.command === \"nytrix.formatFile\", \"import fix should call nytrix.formatFile\");\n\n  const optimizeAction = actions.find((action) => action.title === \"Apply Nytrix optimizations\");\n  assert(optimizeAction.command && optimizeAction.command.command === \"nytrix.optimizeFile\", \"optimize fix should call nytrix.optimizeFile\");\n\n  fakeVscode.languages.getDiagnostics = () => ([\n    { severity: fakeVscode.DiagnosticSeverity.Error, source: \"nytrix\", message: \"broken\", code: \"E1001\" },\n    { severity: fakeVscode.DiagnosticSeverity.Warning, source: \"nytrix-analyze\", message: \"style\", code: \"NYFMT1300\" }\n  ]);\n  const counts = extension.__test.summarizeDiagnosticCounts(fakeVscode.languages.getDiagnostics());\n  assert.strictEqual(counts.error, 1, \"expected one error\");\n  assert.strictEqual(counts.warning, 1, \"expected one warning\");\n  assert.strictEqual(counts.fixable, 1, \"expected one fixable issue\");\n  assert.strictEqual(extension.__test.formatDiagnosticCountsLabel(counts), \"1 error, 1 warning\");\n  assert(\n    extension.__test.formatErrorLensMessage(fakeVscode.languages.getDiagnostics()[0]).includes(\"error [E1001]\"),\n    \"error lens label should include severity and code\"\n  );\n\n  const lensProvider = new extension.__test.NytrixCodeLensProvider();\n  const lenses = lensProvider.provideCodeLenses(document);\n  const lensTitles = lenses.map((lens) => lens.command && lens.command.title).filter(Boolean);\n  assert(lensTitles.includes(\"Problems: 1 error, 1 warning\"), \"missing problems summary lens\");\n  assert(lensTitles.includes(\"Fixable: 1 issue\"), \"missing fixable summary lens\");\n\n}\n\nmodule.exports = main;\n",
  "./debug_symbol_smoke": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst { Position, Range, document, fileUri } = require(\"./harness\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nlet shownDocument = null;\n\nconst fakeVscode = {\n  Position,\n  Range,\n  Uri: { file: fileUri },\n  SymbolKind: {\n    Module: 1,\n    Struct: 2,\n    Enum: 3,\n    TypeParameter: 4,\n    Operator: 5,\n    Constant: 6,\n    Variable: 7,\n    Function: 8\n  },\n  CompletionItemKind: {\n    Module: 1,\n    Struct: 2,\n    Enum: 3,\n    TypeParameter: 4,\n    Constant: 5,\n    Variable: 6,\n    Function: 7,\n    Keyword: 8\n  },\n  workspace: {\n    workspaceFolders: [{ uri: fileUri(\"/workspace\") }],\n    textDocuments: [],\n    getConfiguration() {\n      const values = {\n        \"debug.compilerArguments\": [\"--safe-mode\"],\n        \"debug.dwarfVersion\": 5,\n        \"debug.sourceFileMap\": { \"/remote\": \"/local\" },\n        \"debug.debugLocals\": true,\n        \"debug.justMyCode\": false,\n        \"debug.traceRuntime\": true,\n        \"debug.traceValues\": true,\n        \"debug.traceVerbose\": false,\n        \"debug.traceFilter\": \"main\",\n        \"debug.outputDir\": \"/workspace/out\",\n        \"test.runtimeSuitePath\": \"etc/tests/rt\"\n      };\n      return {\n        get(key, fallback) {\n          return Object.prototype.hasOwnProperty.call(values, key) ? values[key] : fallback;\n        }\n      };\n    },\n    getWorkspaceFolder() {\n      return { uri: fileUri(\"/workspace\") };\n    },\n    findFiles() {\n      return Promise.resolve([]);\n    },\n    openTextDocument(uri) {\n      const found = this.textDocuments.find((doc) => doc.uri.toString() === uri.toString());\n      return found ? Promise.resolve(found) : Promise.reject(new Error(\"missing document\"));\n    },\n    createFileSystemWatcher() {\n      return {\n        onDidCreate() {},\n        onDidChange() {},\n        onDidDelete() {},\n        dispose() {}\n      };\n    }\n  },\n  window: {\n    activeTextEditor: null,\n    showInputBox() {\n      return Promise.resolve(\"local_sum\");\n    },\n    showQuickPick(items) {\n      return Promise.resolve(items[0]);\n    },\n    showTextDocument(uri, options) {\n      shownDocument = { uri, options };\n      return Promise.resolve();\n    },\n    showWarningMessage() {},\n    showInformationMessage() {}\n  },\n  languages: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nfunction compilerSymbol(document, symbol) {\n  return extension.__test.compilerArtifactToSymbols(document, {\n    symbols: [{ kind: \"fn\", line: 1, col: 1, ...symbol }]\n  })[0];\n}\n\nasync function main() {\n  const base = extension.__test.resolveNytrixDebugConfig(\n    { uri: fileUri(\"/workspace\") },\n    {\n      request: \"launch\",\n      name: \"Smoke\",\n      program: \"/workspace/main.ny\",\n      cwd: \"/workspace\",\n      args: [\"one\", \"two\"],\n      env: { NYTRIX_SMOKE: \"1\" },\n      nyPath: \"/tool/ny\",\n      compilerArgs: [\"-O0\"],\n      sourceFileMap: { \"/remote\": \"/local\" },\n      outputDir: \"/workspace/dbg\"\n    }\n  );\n  assert.strictEqual(base.program, \"/workspace/main.ny\");\n  assert.strictEqual(base.cwd, \"/workspace\");\n  assert.deepStrictEqual(base.args, [\"one\", \"two\"]);\n  assert.deepStrictEqual(base.env, { NYTRIX_SMOKE: \"1\" });\n  assert.strictEqual(base.nyPath, \"/tool/ny\");\n  assert.strictEqual(base.outputDir, \"/workspace/dbg\");\n  assert(base.compilerArgs.includes(\"--dwarf-version=5\"), \"debug config should append configured DWARF version\");\n\n  const overridden = extension.__test.resolveNytrixDebugConfig(\n    { uri: fileUri(\"/workspace\") },\n    {\n      request: \"launch\",\n      program: \"/workspace/main.ny\",\n      nyPath: \"/tool/ny\",\n      compilerArgs: [\"--dwarf-version=4\"],\n      dwarfVersion: 5\n    }\n  );\n  assert.deepStrictEqual(\n    overridden.compilerArgs.filter((arg) => String(arg).startsWith(\"--dwarf-version\")),\n    [\"--dwarf-version=4\"],\n    \"debug config should not duplicate explicit DWARF compiler args\"\n  );\n\n  const current = document(\"/workspace/current.ny\", [\n    \"fn local_sum(int a, int b) int {\",\n    \"   return a + b\",\n    \"}\",\n    \"fn local_other() int {\",\n    \"   return local_sum(1, 2)\",\n    \"}\"\n  ].join(\"\\n\"));\n  const std = document(\"/workspace/lib/math/mod.ny\", [\n    \"fn local_sum_extra(int a) int {\",\n    \"   return a\",\n    \"}\",\n    \"fn clamp(int x, int lo, int hi) int {\",\n    \"   return x\",\n    \"}\"\n  ].join(\"\\n\"));\n  fakeVscode.workspace.textDocuments = [current, std];\n  fakeVscode.window.activeTextEditor = {\n    document: current,\n    selection: { active: new Position(4, 16) }\n  };\n\n  const index = new extension.__test.NytrixSymbolIndex();\n  index.updateDocument(current);\n  index.updateDocument(std);\n  const localSymbols = index.documentSymbols(current);\n  assert.strictEqual(localSymbols[0].signature, \"fn local_sum(int a, int b) int\", \"local signatures should use current syntax\");\n  const artifactSymbol = compilerSymbol(current, {\n    name: \"local_sum\",\n    signature: \"fn local_sum(any a, Result<dict, str> b) int\",\n    doc: \"Adds two values.\"\n  });\n  assert(artifactSymbol, \"compiler symbol artifact should map to index symbols\");\n  assert.strictEqual(artifactSymbol.range.start.line, 0, \"compiler symbol line should become zero-based\");\n  assert.strictEqual(artifactSymbol.range.start.character, 3, \"compiler symbol range should select the function name\");\n  assert.strictEqual(artifactSymbol.signature, \"fn local_sum(any a, Result<dict, str> b) int\", \"compiler signatures should stay compact\");\n  const structuredSymbol = compilerSymbol(current, {\n    name: \"local_structured\",\n    params: [{ name: \"path\", type: \"str\" }],\n    return: \"Result<dict, str>\"\n  });\n  assert.strictEqual(structuredSymbol.signature, \"fn local_structured(str path) Result<dict, str>\", \"structured compiler symbols should format signatures\");\n  index.updateCompilerFacts({\n    type_groups: {\n      integer: [\"int\", \"u64\"],\n      seq: [\"list\", \"bytes\"]\n    }\n  });\n  const compilerCompletions = index.compilerCompletionNames();\n  assert(compilerCompletions.typeGroups.includes(\"integer\"), \"compiler type groups should feed fallback completions\");\n  assert(compilerCompletions.types.includes(\"u64\"), \"compiler concrete types should feed fallback completions\");\n  const matches = await index.searchSymbols(\"local_sum\", current.uri.toString());\n  assert(matches.length >= 2, \"expected fuzzy symbol matches\");\n  assert.strictEqual(matches[0].name, \"local_sum\", \"current-file exact match should rank first\");\n\n  await extension.__test.findDefinitionByName(index);\n  assert(shownDocument, \"findDefinitionByName should open a document\");\n  assert.strictEqual(shownDocument.uri.fsPath, \"/workspace/current.ny\");\n  assert.strictEqual(shownDocument.options.selection.start.line, 0);\n  assert.strictEqual(extension.__test.runtimeSuitePath(), \"etc/tests/rt\");\n\n}\n\nmodule.exports = main;\n",
  "./extension_root.js": "\"use strict\";\n\nconst fs = require(\"fs\");\nconst path = require(\"path\");\n\nfunction exists(...parts) {\n  return fs.existsSync(path.join(...parts));\n}\n\nfunction walkUp(starts) {\n  const seen = new Set();\n  const out = [];\n  for (const start of starts.filter(Boolean)) {\n    let current = path.resolve(start);\n    while (!seen.has(current)) {\n      seen.add(current);\n      out.push(current);\n      const parent = path.dirname(current);\n      if (parent === current) break;\n      current = parent;\n    }\n  }\n  return out;\n}\n\nfunction isExtensionRoot(dir) {\n  return Boolean(\n    dir &&\n      exists(dir, \"package.json\") &&\n      exists(dir, \"src\", \"extension.js\") &&\n      exists(dir, \"nytrix.tmLanguage.json\")\n  );\n}\n\nfunction isNytrixRoot(dir) {\n  return Boolean(dir && exists(dir, \"lib\") && (exists(dir, \"make\") || exists(dir, \"build\", \"release\")));\n}\n\nfunction findExtensionRoot() {\n  if (process.env.NYTRIX_VSCODE_EXTENSION_ROOT) {\n    return path.resolve(process.env.NYTRIX_VSCODE_EXTENSION_ROOT);\n  }\n  for (const candidate of walkUp([__dirname, process.cwd()])) {\n    if (isExtensionRoot(candidate)) return candidate;\n  }\n  throw new Error(\"cannot find VS Code Nytrix extension root\");\n}\n\nfunction findNytrixRoot() {\n  if (process.env.NYTRIX_REPO_ROOT) {\n    return path.resolve(process.env.NYTRIX_REPO_ROOT);\n  }\n  const candidates = walkUp([\n    process.cwd(),\n    __dirname,\n    path.resolve(__dirname, \"..\"),\n    path.join(process.env.HOME || \"\", \"nytrix\")\n  ]).filter(isNytrixRoot);\n\n  for (const binary of [\"ny-lsp\", \"ny\"]) {\n    const withBinary = candidates.find((candidate) => exists(candidate, \"build\", \"release\", binary));\n    if (withBinary) return withBinary;\n  }\n  return candidates[0] || path.resolve(findExtensionRoot(), \"..\");\n}\n\nmodule.exports = {\n  findExtensionRoot,\n  findNytrixRoot,\n  isExtensionRoot,\n  isNytrixRoot\n};\n",
  "./harness.js": "\"use strict\";\n\nfunction formatError(err) {\n  return err && err.stack ? err.stack : String(err);\n}\n\nasync function runAll(cases) {\n  const started = Date.now();\n  let passed = 0;\n  try {\n    for (const [name, main] of cases) {\n      const caseStarted = Date.now();\n      await main();\n      passed += 1;\n      console.log(`${name}: ok (${Date.now() - caseStarted}ms)`);\n    }\n    console.log(`js smoke: ${passed}/${cases.length} passed in ${Date.now() - started}ms`);\n  } catch (err) {\n    console.error(formatError(err));\n    console.error(`js smoke: ${passed}/${cases.length} passed before failure`);\n    process.exit(1);\n  }\n}\n\nclass Position {\n  constructor(line, character) {\n    this.line = line;\n    this.character = character;\n  }\n}\n\nclass Range {\n  constructor(startLine, startCharacter, endLine, endCharacter) {\n    this.start = new Position(startLine, startCharacter);\n    this.end = new Position(endLine, endCharacter);\n  }\n}\n\nfunction fileUri(filePath) {\n  return {\n    scheme: \"file\",\n    fsPath: filePath,\n    toString() {\n      return filePath;\n    }\n  };\n}\n\nfunction document(filePath, text) {\n  const lines = text.split(/\\r?\\n/);\n  return {\n    languageId: \"nytrix\",\n    uri: fileUri(filePath),\n    lineCount: lines.length,\n    getText(range) {\n      if (!range) return text;\n      return range.start.line === range.end.line\n        ? lines[range.start.line].slice(range.start.character, range.end.character)\n        : \"\";\n    },\n    lineAt(index) {\n      return { text: lines[index] };\n    },\n    getWordRangeAtPosition(position, regex = /[A-Za-z_][A-Za-z0-9_.]*/g) {\n      const line = lines[position.line] || \"\";\n      const flags = regex.flags.includes(\"g\") ? regex.flags : `${regex.flags}g`;\n      const word = new RegExp(regex.source, flags);\n      let match;\n      while ((match = word.exec(line))) {\n        const start = match.index;\n        const end = start + match[0].length;\n        if (position.character >= start && position.character <= end) {\n          return new Range(position.line, start, position.line, end);\n        }\n      }\n      return null;\n    }\n  };\n}\n\nmodule.exports = { runAll, Position, Range, fileUri, document };\n",
  "./vscode_stub.js": "\"use strict\";\n\nconst Module = require(\"module\");\nconst path = require(\"path\");\nconst { findExtensionRoot } = require(\"./extension_root\");\n\nfunction loadExtensionWithVscode(fakeVscode) {\n  const extensionPath = path.join(findExtensionRoot(), \"src\", \"extension.js\");\n  const previous = Module._load;\n  Module._load = function patchedLoad(request, parent, isMain) {\n    if (request === \"vscode\") {\n      return fakeVscode;\n    }\n    return previous.call(this, request, parent, isMain);\n  };\n  try {\n    delete require.cache[require.resolve(extensionPath)];\n    return require(extensionPath);\n  } finally {\n    Module._load = previous;\n  }\n}\n\nmodule.exports = {\n  loadExtensionWithVscode\n};\n",
  "./metadata_smoke.js": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst fs = require(\"fs\");\nconst path = require(\"path\");\nconst { findExtensionRoot } = require(\"./extension_root\");\nconst { productionDependencyDirs } = require(\"../scripts/package\");\n\nconst root = findExtensionRoot();\nconst read = (...parts) => fs.readFileSync(path.join(root, ...parts), \"utf8\");\nconst json = (...parts) => JSON.parse(read(...parts));\n\nconst manifest = json(\"package.json\");\nconst grammar = json(\"nytrix.tmLanguage.json\");\nconst snippets = json(\"snippets\", \"nytrix.code-snippets\");\nconst extensionSource = read(\"src\", \"extension.js\");\n\nfunction regexSet(text, pattern, map = (match) => match[1]) {\n  return new Set([...String(text).matchAll(pattern)].map(map));\n}\n\nfunction commandActivations() {\n  return new Set((manifest.activationEvents || [])\n    .filter((event) => event.startsWith(\"onCommand:nytrix.\"))\n    .map((event) => event.slice(\"onCommand:\".length)));\n}\n\nfunction contributedCommands() {\n  return new Set((manifest.contributes.commands || []).map((command) => command.command));\n}\n\nfunction registeredCommands() {\n  return regexSet(extensionSource, /\\[\\s*\"(nytrix\\.[A-Za-z0-9_.-]+)\"\\s*,/g);\n}\n\nfunction walkthroughCommands() {\n  const events = (manifest.contributes.walkthroughs || [])\n    .flatMap((walkthrough) => walkthrough.steps || [])\n    .flatMap((step) => step.completionEvents || []);\n  return new Set(events\n    .filter((event) => event.startsWith(\"onCommand:nytrix.\"))\n    .map((event) => event.slice(\"onCommand:\".length)));\n}\n\nfunction configKeysFromCode() {\n  return regexSet(extensionSource, /cfg\\(\\)\\.get\\(\"([^\"]+)\"/g, (match) => `nytrix.${match[1]}`);\n}\n\nfunction flattenStrings(value) {\n  if (typeof value === \"string\") return [value];\n  if (Array.isArray(value)) return value.flatMap(flattenStrings);\n  return value && typeof value === \"object\" ? Object.values(value).flatMap(flattenStrings) : [];\n}\n\nfunction assertSubset(name, subset, superset) {\n  const missing = [...subset].filter((item) => !superset.has(item)).sort();\n  assert.strictEqual(missing.length, 0, `${name} missing: ${missing.join(\", \")}`);\n}\n\nfunction assertNoOverlap(name, left, right) {\n  const overlap = [...left].filter((item) => right.has(item)).sort();\n  assert.strictEqual(overlap.length, 0, `${name}: ${overlap.join(\", \")}`);\n}\n\nfunction assertLineListContains(name, file, required) {\n  const lines = new Set(read(file).split(/\\r?\\n/).map((line) => line.trim()).filter(Boolean));\n  const missing = required.filter((line) => !lines.has(line));\n  assert.strictEqual(missing.length, 0, `${name} missing: ${missing.join(\", \")}`);\n}\n\nfunction relativePackageDirs() {\n  return new Set(productionDependencyDirs(root).map((dir) => path.relative(root, dir).replace(/\\\\/g, \"/\")));\n}\n\nfunction main() {\n  assert.strictEqual(manifest.version, \"0.1.7\", \"package version should be bumped\");\n  assert.strictEqual(manifest.scripts.prepackage, \"npm run validate\", \"package should validate before building the VSIX\");\n  assert.strictEqual(manifest.scripts.package, \"node scripts/package.js\", \"package should use deterministic package-lock dependency discovery\");\n  assert.strictEqual(manifest.scripts[\"package:ls\"], \"node scripts/package.js --list\", \"package listing should use the same deterministic dependency discovery\");\n  assert.strictEqual(manifest.galleryBanner.color, \"#0D1117\", \"marketplace banner should match the Nytrix dark background\");\n  assert.strictEqual(manifest.qna, \"https://github.com/nytrix-lang/nytrix/issues\", \"Q&A should point at the issue tracker\");\n  assert.deepStrictEqual(manifest.extensionKind, [\"workspace\"], \"extension should run on the workspace side for tool processes\");\n  assert(manifest.capabilities && manifest.capabilities.untrustedWorkspaces, \"workspace trust capabilities should be declared\");\n\n  const activated = commandActivations();\n  const contributed = contributedCommands();\n  const registered = registeredCommands();\n  const hidden = new Set([...registered].filter((command) => !contributed.has(command)));\n\n  assertSubset(\"contributed commands not registered\", contributed, registered);\n  assertSubset(\"hidden registered commands not activated\", hidden, activated);\n  assertSubset(\"walkthrough commands not contributed\", walkthroughCommands(), contributed);\n  assertNoOverlap(\"contributed commands should rely on implicit activation\", activated, contributed);\n  assert((manifest.contributes.walkthroughs || []).length > 0, \"extension should include an onboarding walkthrough\");\n\n  const configProperties = new Set(Object.keys(manifest.contributes.configuration.properties || {}));\n  assertSubset(\"configuration keys used by code but not contributed\", configKeysFromCode(), configProperties);\n\n  for (const file of [\n    \"src/extension.js\", \"nytrix.tmLanguage.json\",\n    \"snippets/nytrix.code-snippets\", \"README.md\", \"LICENSE\",\n    \"logo.png\", \"scripts/package.js\"\n  ]) {\n    assert(fs.existsSync(path.join(root, file)), `missing packaged asset ${file}`);\n  }\n\n  const packageDirs = relativePackageDirs();\n  assertSubset(\"production dependency paths\", new Set([\n    \"\", \"node_modules/vscode-languageclient\", \"node_modules/vscode-jsonrpc\",\n    \"node_modules/vscode-languageserver-protocol\", \"node_modules/vscode-languageserver-types\", \"node_modules/semver\"\n  ]), packageDirs);\n  for (const forbidden of [\"node_modules/@vscode/vsce\", \"node_modules/vscode\", \"test\", \"build\", \"cache\", \"dist\", \"out\"]) {\n    assert(!packageDirs.has(forbidden), `package dependency set should not include ${forbidden}`);\n  }\n\n  const snippetText = flattenStrings(snippets).join(\"\\n\");\n  assert(!/fn\\s+[A-Za-z_][A-Za-z0-9_]*\\([^)]*\\)\\s*:/.test(snippetText), \"snippets should use current function return syntax\");\n  assert(!/\\$\\{[0-9]+:Type\\}:\\s*\\$\\{[0-9]+:field\\}/.test(snippetText), \"field snippets should use type-name order\");\n\n  const declarations = grammar.repository && grammar.repository.declaration && grammar.repository.declaration.patterns || [];\n  assert(declarations.some((pattern) => pattern.name === \"meta.function.definition.nytrix\" && pattern.begin), \"grammar should scope function headers\");\n  assert(declarations.some((pattern) => pattern.name === \"meta.extern.block.nytrix\"), \"grammar should scope extern blocks\");\n  assert(flattenStrings(grammar).some((text) => text.includes(\"meta.parameter.typed.nytrix\")), \"grammar should scope typed parameters\");\n\n  assertLineListContains(\"gitignore generated output rules\", \".gitignore\", [\n    \"*.vsix\", \"node_modules/\", \"build/\", \"cache/\", \"dist/\", \"out/\", \".vscode-test/\", \"test/.artifacts/\"\n  ]);\n  assertLineListContains(\"vscodeignore generated output rules\", \".vscodeignore\", [\n    \"node_modules/**\", \".gitignore\", \"!node_modules/vscode-languageclient/**\",\n    \"scripts/**\", \"test/**\", \"build/**\", \"cache/**\", \"dist/**\", \"out/**\", \"*.vsix\"\n  ]);\n\n}\n\nmodule.exports = main;\n",
  "./bootstrap_smoke.js": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst os = require(\"os\");\nconst path = require(\"path\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nconst fakeVscode = {\n  workspace: {\n    workspaceFolders: [],\n    getConfiguration() {\n      const values = {\n        \"bootstrap.mode\": \"prompt\",\n        \"bootstrap.root\": \"${home}/.cache/nytrix-bootstrap\",\n        \"bootstrap.repo\": \"https://github.com/nytrix-lang/nytrix\",\n        \"bootstrap.ref\": \"main\"\n      };\n      return {\n        get(key, fallback) {\n          return Object.prototype.hasOwnProperty.call(values, key) ? values[key] : fallback;\n        }\n      };\n    }\n  },\n  window: {},\n  languages: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nfunction main() {\n  const root = extension.__test.bootstrapRoot();\n  assert.strictEqual(root, path.join(os.homedir(), \".cache\", \"nytrix-bootstrap\"));\n  assert.strictEqual(extension.__test.bootstrapRepo(), \"https://github.com/nytrix-lang/nytrix\");\n  assert.strictEqual(extension.__test.bootstrapRef(), \"main\");\n\n  const toolPaths = extension.__test.bootstrapToolPaths(\"/tmp/nytrix-bootstrap\");\n  assert.strictEqual(toolPaths.root, \"/tmp/nytrix-bootstrap\");\n  assert(toolPaths.ny.endsWith(\"/build/release/ny\"), \"expected ny path under build/release\");\n  assert(toolPaths.lsp.endsWith(\"/build/release/ny-lsp\"), \"expected ny-lsp path under build/release\");\n  assert(toolPaths.makeScript.endsWith(\"/make\"), \"expected repo make script path\");\n\n  const plan = extension.__test.bootstrapPlan(\"/tmp/nytrix-bootstrap\");\n  assert.strictEqual(plan.repo, \"https://github.com/nytrix-lang/nytrix\");\n  assert.strictEqual(plan.ref, \"main\");\n  assert.deepStrictEqual(\n    plan.cloneArgs,\n    [\"clone\", \"--depth\", \"1\", \"--branch\", \"main\", \"https://github.com/nytrix-lang/nytrix\", \"/tmp/nytrix-bootstrap\"]\n  );\n  assert.strictEqual(plan.buildCommand, plan.paths.makeScript, \"expected non-Windows bootstrap to use repo make script\");\n\n}\n\nmodule.exports = main;\n",
  "./code_actions_smoke.js": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst path = require(\"path\");\nconst { findNytrixRoot } = require(\"./extension_root\");\nconst { Position, Range, fileUri } = require(\"./harness\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nconst repoRoot = findNytrixRoot();\nprocess.env.NYTRIX_FMT = process.env.NYTRIX_FMT || path.join(repoRoot, \"build\", \"release\", \"ny-fmt\");\n\nclass Kind {\n  constructor(value) {\n    this.value = value;\n  }\n\n  append(segment) {\n    return new Kind(`${this.value}.${segment}`);\n  }\n}\n\nclass WorkspaceEdit {\n  constructor() {\n    this.edits = [];\n  }\n\n  insert(uri, position, text) {\n    this.edits.push({ uri, position, text });\n  }\n}\n\nclass CodeAction {\n  constructor(title, kind) {\n    this.title = title;\n    this.kind = kind;\n    this.diagnostics = undefined;\n    this.command = undefined;\n    this.edit = undefined;\n    this.isPreferred = false;\n  }\n}\n\nclass CodeLens {\n  constructor(range, command) {\n    this.range = range;\n    this.command = command;\n  }\n}\n\nconst fakeVscode = {\n  CodeAction,\n  CodeLens,\n  CodeActionKind: {\n    QuickFix: new Kind(\"quickfix\"),\n    Source: new Kind(\"source\"),\n    SourceFixAll: new Kind(\"source.fixAll\"),\n    SourceOrganizeImports: new Kind(\"source.organizeImports\")\n  },\n  WorkspaceEdit,\n  Position,\n  Range,\n  Uri: {\n    file: fileUri\n  },\n  DiagnosticSeverity: {\n    Error: 0,\n    Warning: 1,\n    Information: 2,\n    Hint: 3\n  },\n  languages: {\n    getDiagnostics() {\n      return [];\n    }\n  },\n  workspace: {\n    workspaceFolders: [],\n    textDocuments: [],\n    getConfiguration() {\n      return {\n        get(_key, fallback) {\n          return fallback;\n        }\n      };\n    },\n    getWorkspaceFolder() {\n      return null;\n    }\n  },\n  window: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nasync function main() {\n  const provider = new extension.__test.NytrixCodeActionProvider();\n\n  const lines = [\n    \"use std.os *\",\n    \"use std.core(print)\",\n    \"\",\n    \"fn helper(int value) int {\",\n    \"   return value + 1\",\n    \"}\",\n    \"\",\n    \"print(helper(41))\"\n  ];\n\n  const uri = fakeVscode.Uri.file(\"/tmp/assist_test.ny\");\n  const document = {\n    languageId: \"nytrix\",\n    uri,\n    lineCount: lines.length,\n    lineAt(index) {\n      return { text: lines[index] };\n    }\n  };\n\n  const diagnostics = [\n    {\n      code: \"NYFMT1300\",\n      range: new fakeVscode.Range(0, 11, 0, 12)\n    },\n    {\n      code: \"NYFMT2000\",\n      range: new fakeVscode.Range(3, 0, 3, 1)\n    },\n    {\n      code: \"NYAUD1001\",\n      range: new fakeVscode.Range(3, 0, 3, 1)\n    }\n  ];\n\n  const actions = provider.provideCodeActions(document, new fakeVscode.Range(0, 0, 0, 1), { diagnostics });\n  const titles = actions.map((action) => action.title);\n\n  for (const title of [\n    \"Normalize imports with ny-fmt\",\n    \"Insert doc string stub\",\n    \"Apply Nytrix optimizations\",\n    \"Fix all Nytrix style with ny-fmt\",\n    \"Organize Nytrix imports\",\n    \"Analyze current Nytrix file\",\n    \"Check current Nytrix file\"\n  ]) {\n    assert(titles.includes(title), `missing code action ${title}`);\n  }\n\n  const docAction = actions.find((action) => action.title === \"Insert doc string stub\");\n  assert(docAction && docAction.edit, \"missing doc stub workspace edit\");\n  assert(docAction.edit.edits.length === 1, \"expected one doc edit\");\n  assert(\n    docAction.edit.edits[0].text.includes('\"Describe helper.\"'),\n    \"doc stub should describe helper\"\n  );\n\n  const importAction = actions.find((action) => action.title === \"Normalize imports with ny-fmt\");\n  assert(importAction.command && importAction.command.command === \"nytrix.formatFile\", \"import fix should call nytrix.formatFile\");\n\n  const optimizeAction = actions.find((action) => action.title === \"Apply Nytrix optimizations\");\n  assert(optimizeAction.command && optimizeAction.command.command === \"nytrix.optimizeFile\", \"optimize fix should call nytrix.optimizeFile\");\n\n  fakeVscode.languages.getDiagnostics = () => ([\n    { severity: fakeVscode.DiagnosticSeverity.Error, source: \"nytrix\", message: \"broken\", code: \"E1001\" },\n    { severity: fakeVscode.DiagnosticSeverity.Warning, source: \"nytrix-analyze\", message: \"style\", code: \"NYFMT1300\" }\n  ]);\n  const counts = extension.__test.summarizeDiagnosticCounts(fakeVscode.languages.getDiagnostics());\n  assert.strictEqual(counts.error, 1, \"expected one error\");\n  assert.strictEqual(counts.warning, 1, \"expected one warning\");\n  assert.strictEqual(counts.fixable, 1, \"expected one fixable issue\");\n  assert.strictEqual(extension.__test.formatDiagnosticCountsLabel(counts), \"1 error, 1 warning\");\n  assert(\n    extension.__test.formatErrorLensMessage(fakeVscode.languages.getDiagnostics()[0]).includes(\"error [E1001]\"),\n    \"error lens label should include severity and code\"\n  );\n\n  const lensProvider = new extension.__test.NytrixCodeLensProvider();\n  const lenses = lensProvider.provideCodeLenses(document);\n  const lensTitles = lenses.map((lens) => lens.command && lens.command.title).filter(Boolean);\n  assert(lensTitles.includes(\"Problems: 1 error, 1 warning\"), \"missing problems summary lens\");\n  assert(lensTitles.includes(\"Fixable: 1 issue\"), \"missing fixable summary lens\");\n\n}\n\nmodule.exports = main;\n",
  "./debug_symbol_smoke.js": "\"use strict\";\n\nconst assert = require(\"assert\");\nconst { Position, Range, document, fileUri } = require(\"./harness\");\nconst { loadExtensionWithVscode } = require(\"./vscode_stub\");\n\nlet shownDocument = null;\n\nconst fakeVscode = {\n  Position,\n  Range,\n  Uri: { file: fileUri },\n  SymbolKind: {\n    Module: 1,\n    Struct: 2,\n    Enum: 3,\n    TypeParameter: 4,\n    Operator: 5,\n    Constant: 6,\n    Variable: 7,\n    Function: 8\n  },\n  CompletionItemKind: {\n    Module: 1,\n    Struct: 2,\n    Enum: 3,\n    TypeParameter: 4,\n    Constant: 5,\n    Variable: 6,\n    Function: 7,\n    Keyword: 8\n  },\n  workspace: {\n    workspaceFolders: [{ uri: fileUri(\"/workspace\") }],\n    textDocuments: [],\n    getConfiguration() {\n      const values = {\n        \"debug.compilerArguments\": [\"--safe-mode\"],\n        \"debug.dwarfVersion\": 5,\n        \"debug.sourceFileMap\": { \"/remote\": \"/local\" },\n        \"debug.debugLocals\": true,\n        \"debug.justMyCode\": false,\n        \"debug.traceRuntime\": true,\n        \"debug.traceValues\": true,\n        \"debug.traceVerbose\": false,\n        \"debug.traceFilter\": \"main\",\n        \"debug.outputDir\": \"/workspace/out\",\n        \"test.runtimeSuitePath\": \"etc/tests/rt\"\n      };\n      return {\n        get(key, fallback) {\n          return Object.prototype.hasOwnProperty.call(values, key) ? values[key] : fallback;\n        }\n      };\n    },\n    getWorkspaceFolder() {\n      return { uri: fileUri(\"/workspace\") };\n    },\n    findFiles() {\n      return Promise.resolve([]);\n    },\n    openTextDocument(uri) {\n      const found = this.textDocuments.find((doc) => doc.uri.toString() === uri.toString());\n      return found ? Promise.resolve(found) : Promise.reject(new Error(\"missing document\"));\n    },\n    createFileSystemWatcher() {\n      return {\n        onDidCreate() {},\n        onDidChange() {},\n        onDidDelete() {},\n        dispose() {}\n      };\n    }\n  },\n  window: {\n    activeTextEditor: null,\n    showInputBox() {\n      return Promise.resolve(\"local_sum\");\n    },\n    showQuickPick(items) {\n      return Promise.resolve(items[0]);\n    },\n    showTextDocument(uri, options) {\n      shownDocument = { uri, options };\n      return Promise.resolve();\n    },\n    showWarningMessage() {},\n    showInformationMessage() {}\n  },\n  languages: {}\n};\n\nconst extension = loadExtensionWithVscode(fakeVscode);\n\nfunction compilerSymbol(document, symbol) {\n  return extension.__test.compilerArtifactToSymbols(document, {\n    symbols: [{ kind: \"fn\", line: 1, col: 1, ...symbol }]\n  })[0];\n}\n\nasync function main() {\n  const base = extension.__test.resolveNytrixDebugConfig(\n    { uri: fileUri(\"/workspace\") },\n    {\n      request: \"launch\",\n      name: \"Smoke\",\n      program: \"/workspace/main.ny\",\n      cwd: \"/workspace\",\n      args: [\"one\", \"two\"],\n      env: { NYTRIX_SMOKE: \"1\" },\n      nyPath: \"/tool/ny\",\n      compilerArgs: [\"-O0\"],\n      sourceFileMap: { \"/remote\": \"/local\" },\n      outputDir: \"/workspace/dbg\"\n    }\n  );\n  assert.strictEqual(base.program, \"/workspace/main.ny\");\n  assert.strictEqual(base.cwd, \"/workspace\");\n  assert.deepStrictEqual(base.args, [\"one\", \"two\"]);\n  assert.deepStrictEqual(base.env, { NYTRIX_SMOKE: \"1\" });\n  assert.strictEqual(base.nyPath, \"/tool/ny\");\n  assert.strictEqual(base.outputDir, \"/workspace/dbg\");\n  assert(base.compilerArgs.includes(\"--dwarf-version=5\"), \"debug config should append configured DWARF version\");\n\n  const overridden = extension.__test.resolveNytrixDebugConfig(\n    { uri: fileUri(\"/workspace\") },\n    {\n      request: \"launch\",\n      program: \"/workspace/main.ny\",\n      nyPath: \"/tool/ny\",\n      compilerArgs: [\"--dwarf-version=4\"],\n      dwarfVersion: 5\n    }\n  );\n  assert.deepStrictEqual(\n    overridden.compilerArgs.filter((arg) => String(arg).startsWith(\"--dwarf-version\")),\n    [\"--dwarf-version=4\"],\n    \"debug config should not duplicate explicit DWARF compiler args\"\n  );\n\n  const current = document(\"/workspace/current.ny\", [\n    \"fn local_sum(int a, int b) int {\",\n    \"   return a + b\",\n    \"}\",\n    \"fn local_other() int {\",\n    \"   return local_sum(1, 2)\",\n    \"}\"\n  ].join(\"\\n\"));\n  const std = document(\"/workspace/lib/math/mod.ny\", [\n    \"fn local_sum_extra(int a) int {\",\n    \"   return a\",\n    \"}\",\n    \"fn clamp(int x, int lo, int hi) int {\",\n    \"   return x\",\n    \"}\"\n  ].join(\"\\n\"));\n  fakeVscode.workspace.textDocuments = [current, std];\n  fakeVscode.window.activeTextEditor = {\n    document: current,\n    selection: { active: new Position(4, 16) }\n  };\n\n  const index = new extension.__test.NytrixSymbolIndex();\n  index.updateDocument(current);\n  index.updateDocument(std);\n  const localSymbols = index.documentSymbols(current);\n  assert.strictEqual(localSymbols[0].signature, \"fn local_sum(int a, int b) int\", \"local signatures should use current syntax\");\n  const artifactSymbol = compilerSymbol(current, {\n    name: \"local_sum\",\n    signature: \"fn local_sum(any a, Result<dict, str> b) int\",\n    doc: \"Adds two values.\"\n  });\n  assert(artifactSymbol, \"compiler symbol artifact should map to index symbols\");\n  assert.strictEqual(artifactSymbol.range.start.line, 0, \"compiler symbol line should become zero-based\");\n  assert.strictEqual(artifactSymbol.range.start.character, 3, \"compiler symbol range should select the function name\");\n  assert.strictEqual(artifactSymbol.signature, \"fn local_sum(any a, Result<dict, str> b) int\", \"compiler signatures should stay compact\");\n  const structuredSymbol = compilerSymbol(current, {\n    name: \"local_structured\",\n    params: [{ name: \"path\", type: \"str\" }],\n    return: \"Result<dict, str>\"\n  });\n  assert.strictEqual(structuredSymbol.signature, \"fn local_structured(str path) Result<dict, str>\", \"structured compiler symbols should format signatures\");\n  index.updateCompilerFacts({\n    type_groups: {\n      integer: [\"int\", \"u64\"],\n      seq: [\"list\", \"bytes\"]\n    }\n  });\n  const compilerCompletions = index.compilerCompletionNames();\n  assert(compilerCompletions.typeGroups.includes(\"integer\"), \"compiler type groups should feed fallback completions\");\n  assert(compilerCompletions.types.includes(\"u64\"), \"compiler concrete types should feed fallback completions\");\n  const matches = await index.searchSymbols(\"local_sum\", current.uri.toString());\n  assert(matches.length >= 2, \"expected fuzzy symbol matches\");\n  assert.strictEqual(matches[0].name, \"local_sum\", \"current-file exact match should rank first\");\n\n  await extension.__test.findDefinitionByName(index);\n  assert(shownDocument, \"findDefinitionByName should open a document\");\n  assert.strictEqual(shownDocument.uri.fsPath, \"/workspace/current.ny\");\n  assert.strictEqual(shownDocument.options.selection.start.line, 0);\n  assert.strictEqual(extension.__test.runtimeSuitePath(), \"etc/tests/rt\");\n\n}\n\nmodule.exports = main;\n"
};
const moduleCache = {};

function normalizeLocal(request) {
  return request.endsWith(".js") ? request : `${request}.js`;
}

function localId(request) {
  const stripped = request.replace(/^\.\//, "");
  const base = stripped.endsWith(".js") ? stripped.slice(0, -3) : stripped;
  return `./${base}`;
}

function compactRequire(fromFile, request) {
  if (request.startsWith("./")) {
    const id = localId(request);
    if (Object.prototype.hasOwnProperty.call(moduleSources, id)) {
      return loadCompactModule(id);
    }
    if (Object.prototype.hasOwnProperty.call(moduleSources, `${id}.js`)) {
      return loadCompactModule(`${id}.js`);
    }
  }
  return Module.createRequire(path.join(__dirname, fromFile))(request);
}

function compactRequireFor(fromFile) {
  const nativeRequire = Module.createRequire(path.join(__dirname, fromFile));
  const req = (request) => compactRequire(fromFile, request);
  req.resolve = nativeRequire.resolve.bind(nativeRequire);
  req.cache = require.cache;
  req.extensions = require.extensions;
  req.main = require.main;
  return req;
}

function loadCompactModule(id) {
  if (moduleCache[id]) return moduleCache[id].exports;
  const filename = path.join(__dirname, id.replace(/^\.\//, ""));
  const module = { exports: {} };
  moduleCache[id] = module;
  const wrapped = new Function("require", "module", "exports", "__filename", "__dirname", moduleSources[id]);
  wrapped(compactRequireFor(id.replace(/^\.\//, "")), module, module.exports, filename, __dirname);
  return module.exports;
}

function formatError(err) {
  return err && err.stack ? err.stack : String(err);
}

async function runAll(cases) {
  const started = Date.now();
  let passed = 0;
  try {
    for (const [name, main] of cases) {
      const caseStarted = Date.now();
      await main();
      passed += 1;
      console.log(`${name}: ok (${Date.now() - caseStarted}ms)`);
    }
    console.log(`js smoke: ${passed}/${cases.length} passed in ${Date.now() - started}ms`);
  } catch (err) {
    console.error(formatError(err));
    console.error(`js smoke: ${passed}/${cases.length} passed before failure`);
    process.exit(1);
  }
}

runAll([
  ["metadata smoke", loadCompactModule("./metadata_smoke")],
  ["bootstrap smoke", loadCompactModule("./bootstrap_smoke")],
  ["code action smoke", loadCompactModule("./code_actions_smoke")],
  ["debug symbol smoke", loadCompactModule("./debug_symbol_smoke")]
]);
